@Override
		public void update() {

			if(!this.world.isRemote) {

				if(delay <= 0) {

					if(this.isRetracting && this.extend > 0) {
						this.extend--;
					} else if(!this.isRetracting) {
						this.extend++;

						if(this.extend >= this.maxExtend) {
							this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.pressOperate", 1.0F, 1.5F);

							ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
							Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + dir.offsetX * 2, this.pos.getY() + dir.offsetY * 2, this.pos.getZ() + dir.offsetZ * 2).getBlock();

							if(b instanceof IInsertable && ((IInsertable) b).insertItem(this.world, this.pos.getX() + dir.offsetX * 2, this.pos.getY() + dir.offsetY * 2, this.pos.getZ() + dir.offsetZ * 2, dir, slot)) {
								this.decrStackSize(0, 1);
							}

							this.isRetracting = true;
							this.delay = 5;
						}
					}

				} else {
					delay--;
				}

				networkPackNT(25);

			} else {
				this.lastExtend = this.renderExtend;

				if(this.turnProgress > 0) {
					this.renderExtend += (this.syncExtend - this.renderExtend) / (double) this.turnProgress;
					this.turnProgress--;
				} else {
					this.renderExtend = this.syncExtend;
				}
			}

		}

@Override
	public boolean onBlockActivated(World world, int x, int y, int z, EntityPlayer player, int side, float hitX, float hitY, float hitZ) {
		if(world.isRemote) {
			return true;
		} else if(!player.isSneaking()) {
			TileEntityRadiobox box = (TileEntityRadiobox)world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y, z));

			if(com.hbm.util.NativeHeldItem.getMainHandNullable(player) != null && com.hbm.util.NativeHeldItem.getMainHandNullable(player).getItem() == ModItems.battery_spark && !box.infinite) {
				com.hbm.util.NativeHeldItem.getMainHandNullable(player).stackSize--;
				world.playSoundEffect(x + 0.5, y + 0.5, z + 0.5, "hbm:item.upgradePlug", 1.5F, 1.0F);
				box.infinite = true;
				box.markDirty();
				return true;
			}

			int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );
			if(meta <= 5) {
				world.setBlockMetadataWithNotify(x, y, z, meta + 4, 2);
				world.playSoundEffect(x, y, z, "hbm:block.reactorStart", 1.0F, 1.0F);
			} else {
				world.setBlockMetadataWithNotify(x, y, z, meta - 4, 2);
				world.playSoundEffect(x, y, z, "hbm:block.reactorStart", 1.0F, 0.85F);
			}

			return true;
		} else {
			return false;
		}
	}

