public void handleButtonPacket(int value, int meta) {

		if(meta == 0 && this.isLoaded()) {
			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbStart", 5.0F, 1.0F);
			started = true;
		}

		if(meta == 1)
			timer = value * 20;
	}

public void update() {
		if(this.world.isRemote) return;

		Block block = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ()).getBlock();

		if(!(block instanceof Landmine)) return;
		Landmine landmine = (Landmine) block;

		double range = landmine.range;
		double height = landmine.height;

		if(waitingForPlayer) {
			range = 25;
			height = 25;
		} else if(!isPrimed) {
			range *= 2;
			height *= 2;
		}

		if(!com.hbm.world.WorldBlockState.read(this.world, this.pos.getX(), this.pos.getY() + 1, this.pos.getZ()).getBlock().isAir(this.world, this.pos.getX(), this.pos.getY() + 1, this.pos.getZ())) return;

		List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - range, this.pos.getY() - height, this.pos.getZ() - range, this.pos.getX() + range + 1, this.pos.getY() + height, this.pos.getZ() + range + 1));

		for(Entity entity : list) {

			if(entity.isCreatureType(EnumCreatureType.waterCreature, false)) continue;
			if(entity.isCreatureType(EnumCreatureType.ambient, false)) continue;

			if(waitingForPlayer) {
				// This mine has been generated by worldgen and is ignoring mobs until a player is close enough
				// This is to prevent worldgen mines from detonating well before they become gameplay relevant

				if(entity instanceof EntityPlayer) {
					waitingForPlayer = false;
					return;
				}
			} else {
				if(entity instanceof EntityLivingBase) {

					if(isPrimed) {
						//the explosion is part of the mine block so that the IBomb interface works, i remember now
						landmine.explode(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ());
						if(entity instanceof EntityPlayer) ((EntityPlayer) entity).addStat(MainRegistry.statMines, 1);
					}

					return;
				}
			}
		}

		// After placing, the mine needs to prime itself in order to not immediately kill the placer
		// The mine will prime itself only after all entities have left its trigger radius * 2
		// I'm leaving this note because I made a dumb assumption on what this was meant to do
		if(!isPrimed && !waitingForPlayer) {
			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.fstbmbStart", 3.0F, 1.0F);
			isPrimed = true;
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.prevLift = this.lift;
			this.prevErector = this.erector;

			float erectorSpeed = 1.5F;
			float liftSpeed = 0.025F;

			if(this.isMissileValid()) {
				if(slots[0].getItem() instanceof ItemMissile) {
					ItemMissile missile = (ItemMissile) slots[0].getItem();
					this.formFactor = missile.formFactor.ordinal();

					if(missile.formFactor == MissileFormFactor.ATLAS || missile.formFactor == MissileFormFactor.HUGE) {
						erectorSpeed /= 2F;
						liftSpeed /= 2F;
					}
				}

				if(this.erector == 90F && this.lift == 1F) {
					this.readyToLoad = true;
				}
			} else {
				readyToLoad = false;
				erected = false;
				delay = 20;
			}

			if(this.power >= 75_000) {
				if(delay > 0) {
					delay--;

					if(delay < 10 && scheduleErect) {
						this.erected = true;
						this.scheduleErect = false;
					}

					// if there is no missile or the missile isn't ready (i.e. the erector hasn't returned to zero position yet), retract
					if(slots[0] == null || !readyToLoad) {
						//fold back erector
						if(erector < 90F) {
							erector = Math.min(erector + erectorSpeed, 90F);
							if(erector == 90F) delay = 20;
						//extend lift
						} else if(lift < 1F) {
							lift = Math.min(lift + liftSpeed, 1F);
							if(erector == 1F) {
								//if the lift is fully extended, the loading can begin
								readyToLoad = true;
								delay = 20;
							}
						}
					}

				} else {

					//only extend if the erector isn't up yet and the missile can be loaded
					if(!erected && readyToLoad) {
						this.state = this.STATE_LOADING;

						//first, rotate the erector
						if(erector != 0F) {
							erector = Math.max(erector - erectorSpeed, 0F);
							if(erector == 0F) delay = 20;
						//then retract the lift
						} else if(lift > 0) {
							lift = Math.max(lift - liftSpeed, 0F);
							if(lift == 0F) {
								//once the lift is at the bottom, the missile is deployed
								scheduleErect = true;
								delay = 20;
							}
						}
					} else {
						//first, fold back the erector
						if(erector < 90F) {
							erector = Math.min(erector + erectorSpeed, 90F);
							if(erector == 90F) delay = 20;
						//then extend the lift again
						} else if(lift < 1F) {
							lift = Math.min(lift + liftSpeed, 1F);
							if(erector == 1F) {
								//if the lift is fully extended, the loading can begin
								readyToLoad = true;
								delay = 20;
							}
						}
					}
				}
			}

			if(!this.hasFuel() || !this.isMissileValid()) this.state = this.STATE_MISSING;
			if(this.erected && this.canLaunch()) this.state = this.STATE_READY;

			boolean prevLiftMoving = this.liftMoving;
			boolean prevErectorMoving = this.erectorMoving;
			this.liftMoving = false;
			this.erectorMoving = false;
			if(this.prevLift != this.lift) this.liftMoving = true;
			if(this.prevErector != this.erector) this.erectorMoving = true;

			if(prevLiftMoving && !this.liftMoving) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:door.wgh_stop", 2F, 1F);
			if(prevErectorMoving && !this.erectorMoving) this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:door.garage_stop", 2F, 1F);

		} else {
			this.prevLift = this.lift;
			this.prevErector = this.erector;

			if(this.sync > 0) {
				this.lift = this.lift + ((this.syncLift - this.lift) / (float) this.sync);
				this.erector = this.erector + ((this.syncErector - this.erector) / (float) this.sync);
				--this.sync;
			} else {
				this.lift = this.syncLift;
				this.erector = this.syncErector;
			}

			if(this.liftMoving) {
				if(this.audioLift == null || !this.audioLift.isPlaying()) {
					this.audioLift = MainRegistry.proxy.getLoopedSound("hbm:door.wgh_start", this.pos.getX(), this.pos.getY(), this.pos.getZ(), 0.75F, 25F, 1.0F, 5);
					this.audioLift.startSound();
				}
				this.audioLift.keepAlive();
			} else {
				if(this.audioLift != null) {
					this.audioLift.stopSound();
					this.audioLift = null;
				}
			}

			if(this.erectorMoving) {
				if(this.audioErector == null || !this.audioErector.isPlaying()) {
					this.audioErector = MainRegistry.proxy.getLoopedSound("hbm:door.garage_move", this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1.5F, 25F, 1.0F, 5);
					this.audioErector.startSound();
				}
				this.audioErector.keepAlive();
			} else {
				if(this.audioErector != null) {
					this.audioErector.stopSound();
					this.audioErector = null;
				}
			}

			if(this.erected && (this.formFactor == MissileFormFactor.HUGE.ordinal() || this.formFactor == MissileFormFactor.ATLAS.ordinal()) && this.tanks[1].getFill() > 0) {
				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "tower");
				data.setFloat("lift", 0F);
				data.setFloat("base", 0.5F);
				data.setFloat("max", 2F);
				data.setInteger("life", 70 + this.world.rand.nextInt(30));
				data.setDouble("posX", this.pos.getX() + 0.5 + this.world.rand.nextGaussian() * 0.5);
				data.setDouble("posZ", this.pos.getZ() + 0.5 + this.world.rand.nextGaussian() * 0.5);
				data.setDouble("posY", this.pos.getY() + 2);
				data.setBoolean("noWind", true);
				data.setFloat("alphaMod", 2F);
				data.setFloat("strafe", 0.05F);
				for(int i = 0; i < 3; i++) MainRegistry.proxy.effectNT(data);
			}

			List<EntityMissileBaseNT> entities = this.world.getEntitiesWithinAABB(EntityMissileBaseNT.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY(), this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 10, this.pos.getZ() + 1.5));

			if(!entities.isEmpty()) {
				for(int i = 0; i < 15; i++) {

					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10);
					if(this.world.rand.nextBoolean()) dir = dir.getOpposite();
					float moX = (float) (this.world.rand.nextGaussian() * 0.15F + 0.75) * dir.offsetX;
					float moZ = (float) (this.world.rand.nextGaussian() * 0.15F + 0.75) * dir.offsetZ;

					NBTTagCompound data = new NBTTagCompound();
					data.setDouble("posX", this.pos.getX() + 0.5);
					data.setDouble("posY", this.pos.getY() + 0.25);
					data.setDouble("posZ", this.pos.getZ() + 0.5);
					data.setString("type", "launchSmoke");
					data.setDouble("moX", moX);
					data.setDouble("moY", 0);
					data.setDouble("moZ", moZ);
					MainRegistry.proxy.effectNT(data);
				}
			}
		}

		super.update();
	}

