					this.trySubscribe(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
					this.trySubscribe(tanks[0].getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
					this.trySubscribe(tanks[1].getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				}
			}

			tanks[0].loadTank(4, 5, slots);
			tanks[1].loadTank(6, 7, slots);

			power = Library.chargeTEFromItems(slots, 8, power, maxPower);

			if(!starting || !canLaunch()) {
				countdown = maxCount;
				starting = false;
			} else if(countdown > 0) {
				countdown--;

				if(countdown % 100 == 0 && countdown > 0)
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:alarm.hatch", 100F, 1.1F);

			} else {
				liftOff();
			}

			networkPackNT(250);
		}

		if(this.world.isRemote) {
			if(!starting || !canLaunch()) {

				if(audio != null) {
					audio.stopSound();
					audio = null;
				}

				countdown = maxCount;

			} else if(countdown > 0) {

				if(audio == null) {
					audio = this.createAudioLoop();
					audio.updateVolume(100);
					audio.startSound();
				} else if(!audio.isPlaying()) {
					audio = rebootAudio(audio);
				}

				countdown--;
			}

			List<EntitySoyuz> entities = this.world.getEntitiesWithinAABB(EntitySoyuz.class, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY(), this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 10, this.pos.getZ() + 1.5));

			if(!entities.isEmpty()) {

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "smoke");
				data.setString("mode", "shockRand");
				data.setInteger("count", 50);
				data.setDouble("strength", this.world.rand.nextGaussian() * 3 + 6);
				data.setDouble("posX", this.pos.getX() + 0.5);
				data.setDouble("posY", this.pos.getY() - 3);
				data.setDouble("posZ", this.pos.getZ() + 0.5);

				MainRegistry.proxy.effectNT(data);
			}
		}
	}

public void liftOff() {

		this.starting = false;

		int req = this.getFuelRequired();
		int pow = this.getPowerRequired();

		EntitySoyuz soyuz = new EntitySoyuz(this.world);
		soyuz.setSkin(this.getType());
		soyuz.mode = this.mode;
		soyuz.setLocationAndAngles(this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, 0, 0);
		this.world.spawnEntityInWorld(soyuz);

		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:entity.soyuzTakeoff", 100F, 1.1F);

		tanks[0].setFill(tanks[0].getFill() - req);
		tanks[1].setFill(tanks[1].getFill() - req);
		power -= pow;

		if(mode == 0) {
			soyuz.setSat(slots[2]);

			if(this.orbital() == 2)
				slots[3] = null;

			slots[2] = null;
		}

		if(mode == 1) {
			List<ItemStack> payload = new ArrayList();

			for(int i = 9; i < 27; i++) {
				payload.add(slots[i]);
				slots[i] = null;
			}

			soyuz.targetX = slots[1].stackTagCompound.getInteger("xCoord");
			soyuz.targetZ = slots[1].stackTagCompound.getInteger("zCoord");
			soyuz.setPayload(payload);
		}

		slots[0] = null;
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(this.buf != null)
				this.buf.release();
			this.buf = Unpooled.buffer();

			this.powerBuffer = 0;

			tanks[0].setTankType(Fluids.STEAM);
			tanks[1].setTankType(Fluids.SPENTSTEAM);

			tanks[0].serialize(buf);

			FT_Coolable trait = tanks[0].getTankType().getTrait(FT_Coolable.class);
			double eff = trait.getEfficiency(CoolingType.TURBINE) * efficiency;

			int inputOps = tanks[0].getFill() / trait.amountReq;
			int outputOps = (tanks[1].getMaxFill() - tanks[1].getFill()) / trait.amountProduced;
			int ops = Math.min(inputOps, outputOps);
			tanks[0].setFill(tanks[0].getFill() - ops * trait.amountReq);
			tanks[1].setFill(tanks[1].getFill() + ops * trait.amountProduced);
			this.powerBuffer += (ops * trait.heatEnergy * eff);

			if(ops > 0) {
				this.acceleration += 0.1F;
			} else {
				this.acceleration -= 0.1F;
			}

			this.acceleration = MathHelper.clamp(this.acceleration, 0F, 40F);
			this.rotor += this.acceleration;

			if(this.rotor >= 360D) {
				this.rotor -= 360D;

				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.steamEngineOperate", getVolume(1.0F), 0.5F + (acceleration / 80F));
			}

			buf.writeLong(this.powerBuffer);
			buf.writeFloat(this.rotor);
			tanks[1].serialize(buf);

			for(DirPos pos : getConPos()) {
				if(this.powerBuffer > 0) this.tryProvide(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.trySubscribe(tanks[0].getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.sendFluid(tanks[1], this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}

			networkPackNT(150);
		} else {
			this.lastRotor = this.rotor;

			if(this.turnProgress > 0) {
				double d = MathHelper.wrapDegrees(this.syncRotor - (double) this.rotor);
				this.rotor = (float) ((double) this.rotor + d / (double) this.turnProgress);
				--this.turnProgress;
			} else {
				this.rotor = this.syncRotor;
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(hasCog) {
				this.powerBuffer = 0;
				tryPullHeat();

				this.powerBuffer = (long) (this.heat * (this.isCreative() ? 1 : this.efficiency));

				if(warnCooldown > 0)
					warnCooldown--;

				if(heat > maxHeat() && !isCreative()) {

					this.overspeed++;

					if(overspeed > 60 && warnCooldown == 0) {
						warnCooldown = 100;
						this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, "hbm:block.warnOverspeed", 2.0F, 1.0F);
					}

					if(overspeed > overspeedLimit) {
						this.hasCog = false;
						this.world.newExplosion(null, this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, 5F, false, false);

						int orientation = this.getBlockMetadata() - BlockDummyable.offset;
						ForgeDirection dir = ForgeDirection.getOrientation(orientation);
						EntityCog cog = new EntityCog(this.world, this.pos.getX() + 0.5 + dir.offsetX, this.pos.getY() + 1, this.pos.getZ() + 0.5 + dir.offsetZ).setOrientation(orientation).setMeta(this.getGeatMeta());
						ForgeDirection rot = dir.getRotation(ForgeDirection.DOWN);

						cog.motionX = rot.offsetX;
						cog.motionY = 1 + (heat - maxHeat()) * 0.0001D;
						cog.motionZ = rot.offsetZ;
						this.world.spawnEntityInWorld(cog);

						this.markDirty();
					}

				} else {
					this.overspeed = 0;
				}
			} else {
				this.overspeed = 0;
				this.warnCooldown = 0;
			}

			networkPackNT(150);

			if(hasCog) {
				for(DirPos pos : getConPos()) {
					this.tryProvide(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				}
			} else {

				if(this.powerBuffer > 0)
					this.powerBuffer--;
			}

			this.heat = 0;
		} else {

			float momentum = powerBuffer * 50F / ((float) maxHeat());

			if(this.isCreative()) momentum = Math.min(momentum, 45F);

			this.lastSpin = this.spin;
			this.spin += momentum;

			if(this.spin >= 360F) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) resetSharedTanks();

		if(!this.world.isRemote && !updateLock()) {

			boolean turnedOn = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX(), this.pos.getY() + 3, this.pos.getZ()).getBlock() == ModBlocks.watz_pump && this.world.getIndirectPowerLevelTo(this.pos.getX(), this.pos.getY() + 5, this.pos.getZ(), 0) > 0;
			List<TileEntityWatz> segments = new ArrayList();
			segments.add(this);
			this.subscribeToTop();

			/* accumulate all segments */
			for(int y = this.pos.getY() - 3; y >= 0; y -= 3) {
				TileEntity tile = Compat.getTileStandard(this.world, this.pos.getX(), y, this.pos.getZ());
				if(tile instanceof TileEntityWatz) {
					segments.add((TileEntityWatz) tile);
				} else {
					break;
				}
			}

			/* set up shared tanks */
			FluidTank[] sharedTanks = new FluidTank[3];
			for(int i = 0; i < 3; i++) sharedTanks[i] = new FluidTank(tanks[i].getTankType(), 0);

			for(TileEntityWatz segment : segments) {
				segment.setupCoolant();
				for(int i = 0; i < 3; i++) {
					sharedTanks[i].changeTankSize(sharedTanks[i].getMaxFill() + segment.tanks[i].getMaxFill());
					sharedTanks[i].setFill(sharedTanks[i].getFill() + segment.tanks[i].getFill());
				}
			}

			//update coolant, bottom to top
			for(int i = segments.size() - 1; i >= 0; i--) {
				TileEntityWatz segment = segments.get(i);
				segment.updateCoolant(sharedTanks);
			}

			/* update reaction, top to bottom */
			this.updateReaction(null, sharedTanks, turnedOn);
			for(int i = 1; i < segments.size(); i++) {
				TileEntityWatz segment = segments.get(i);
				TileEntityWatz above = segments.get(i - 1);
				segment.updateReaction(above, sharedTanks, turnedOn);
			}

			/* send sync packets (order doesn't matter) */
			for(TileEntityWatz segment : segments) {
				segment.sharedTanks[0] = sharedTanks[0];
				segment.sharedTanks[1] = sharedTanks[1];
				segment.sharedTanks[2] = sharedTanks[2];
				segment.isOn = turnedOn;
				segment.networkPackNT(25);
				segment.heat *= 0.99; //cool 1% per tick
			}

			/* re-distribute fluid from shared tanks back into actual tanks, bottom to top */
			for(int i = segments.size() - 1; i >= 0; i--) {
				TileEntityWatz segment = segments.get(i);
				for(int j = 0; j < 3; j++) {
					int min = Math.min(segment.tanks[j].getMaxFill(), sharedTanks[j].getFill());
					sharedTanks[j].setFill(sharedTanks[j].getFill() - min);
					segment.tanks[j].setFill(min);
				}
			}

			segments.get(segments.size() - 1).sendOutBottom();

			/* explode on mud overflow */
			if(sharedTanks[2].getFill() > 0) {
				for(int x = -3; x <= 3; x++) {
					for(int y = 3; y < 6; y++) {
						for(int z = -3; z <= 3; z++) {
							this.world.setBlock(this.pos.getX() + x, this.pos.getY() + y, this.pos.getZ() + z, Blocks.AIR);
						}
					}
				}
				this.disassemble();

				ChunkRadiationManager.proxy.incrementRad(this.world, this.pos.getX(), this.pos.getY() + 1, this.pos.getZ(), 1_000F);

				this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 2, this.pos.getZ() + 0.5, "hbm:block.rbmk_explosion", 50.0F, 1.0F);
				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "rbmkmush");
				data.setFloat("scale", 5);
				PacketDispatcher.wrapper.sendToAllAround(new AuxParticlePacketNT(data, this.pos.getX() + 0.5, this.pos.getY() + 2, this.pos.getZ() + 0.5), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 250));
				MainRegistry.proxy.effectNT(data);

				return;
			}
		}
	}

@Override
	public void receiveFusionPower(long fusionPower, double neutronPower) {
		this.plasmaEnergy = fusionPower;

		int waterCycles = Math.min(tanks[0].getFill(), tanks[1].getMaxFill() - tanks[1].getFill());
		int steamCycles = (int) (Math.min(fusionPower / tanks[0].getTankType().getTrait(FT_Heatable.class).getFirstStep().heatReq, waterCycles));
		// the Math.min call was mushed into the steam cycles call instead of doing it afterwards as usual
		// in order to prevent issues when casting, should the fusion reactor output truly absurd amounts of power
		// due to the water cycles being effectively capped via the buffer size

		if(steamCycles > 0) {
			tanks[0].setFill(tanks[0].getFill() - steamCycles);
			tanks[1].setFill(tanks[1].getFill() + steamCycles);

			if(this.world.rand.nextInt(200) == 0) {
				this.world.playSoundEffect(this.pos.getX() + 0.5, this.pos.getY() + 2, this.pos.getZ() + 0.5, "hbm:block.boilerGroan", 2.5F, 1.0F);
			}
		}
	}

@SuppressWarnings("unchecked")
	public void meltdown() {

		RBMKBase.dropLids = false;

		columns.clear();
		pipes.clear();
		getFF(this.pos.getX(), this.pos.getY(), this.pos.getZ());

		int minX = this.pos.getX();
		int maxX = this.pos.getX();
		int minZ = this.pos.getZ();
		int maxZ = this.pos.getZ();

		//set meltdown bounds
		for(TileEntityRBMKBase rbmk : columns) {

			if(rbmk.getPos().getX() < minX)
				minX = rbmk.getPos().getX();
			if(rbmk.getPos().getX() > maxX)
				maxX = rbmk.getPos().getX();
			if(rbmk.getPos().getZ() < minZ)
				minZ = rbmk.getPos().getZ();
			if(rbmk.getPos().getZ() > maxZ)
				maxZ = rbmk.getPos().getZ();
		}

		for(TileEntityRBMKBase rbmk : columns) {

			int distFromMinX = rbmk.getPos().getX() - minX;
			int distFromMaxX = maxX - rbmk.getPos().getX();
			int distFromMinZ = rbmk.getPos().getZ() - minZ;
			int distFromMaxZ = maxZ - rbmk.getPos().getZ();

			int minDist = Math.min(distFromMinX, Math.min(distFromMaxX, Math.min(distFromMinZ, distFromMaxZ)));

			rbmk.onMelt(minDist + 1);
		}

		for(TileEntityRBMKBase rbmk : columns) {

			if(rbmk instanceof TileEntityRBMKRod && com.hbm.world.WorldBlockState.read(this.world, rbmk.getPos().getX(), rbmk.getPos().getY(), rbmk.getPos().getZ()).getBlock() == ModBlocks.corium_block) {

				for(int x = rbmk.getPos().getX() - 1; x <= rbmk.getPos().getX() + 1; x ++) {
					for(int y = rbmk.getPos().getY() - 1; y <= rbmk.getPos().getY() + 1; y ++) {
						for(int z = rbmk.getPos().getZ() - 1; z <= rbmk.getPos().getZ() + 1; z ++) {

							Block b = com.hbm.world.WorldBlockState.read(this.world, x, y, z).getBlock();

							if(this.world.rand.nextInt(3) == 0 && (b == ModBlocks.pribris || b == ModBlocks.pribris_burning)) {

								if(RBMKBase.digamma)
									this.world.setBlock(x, y, z, ModBlocks.pribris_digamma);
								else
									this.world.setBlock(x, y, z, ModBlocks.pribris_radiating);
							}
						}
					}
				}
			}
		}

		/* Hanlde overpressure event */
		if(RBMKDials.getOverpressure(this.world) && !pipes.isEmpty()) {
			HashSet<FluidNode> pipeBlocks = new HashSet<>();
			HashSet<Map.Entry<IFluidReceiverMK2, Long>> pipeReceivers = new HashSet<>();

			//unify all parts into single sets to prevent redundancy
			pipes.forEach(x -> {
				pipeBlocks.addAll(x.links);
				pipeReceivers.addAll(x.receiverEntries.entrySet());
			});

			int count = 0;
			int max = Math.min(pipeBlocks.size() / 5, 100);
			Iterator<FluidNode> itPipes = pipeBlocks.iterator();
			Iterator<Map.Entry<IFluidReceiverMK2, Long>> itReceivers = pipeReceivers.iterator();

			while(itPipes.hasNext() && count < max) {
				FluidNode node = itPipes.next();
				for (BlockPos pos : node.positions) {
					int x = pos.getX(), y = pos.getY(), z = pos.getZ();
					if (this.world.getTileEntity(new net.minecraft.util.math.BlockPos(x, y ,z)) != null) {
						this.world.setBlock(x, y, z, Blocks.AIR);
					}
				}
				count++;
			}

			while(itReceivers.hasNext()) {
				Map.Entry<IFluidReceiverMK2, Long> e = itReceivers.next();
				IFluidReceiverMK2 con = e.getKey();
				if(con instanceof TileEntity) {
					TileEntity tile = (TileEntity) con;
					if(con instanceof IOverpressurable) {
						((IOverpressurable) con).explode(this.world, tile.getPos().getX(), tile.getPos().getY(), tile.getPos().getZ());
					} else {
						this.world.setBlock(tile.getPos().getX(), tile.getPos().getY(), tile.getPos().getZ(), Blocks.AIR);
						this.world.newExplosion(null, tile.getPos().getX() + 0.5, tile.getPos().getY() + 0.5, tile.getPos().getZ() + 0.5, 5F, false, false);
					}
				}
			}
		}

		int smallDim = Math.min(maxX - minX, maxZ - minZ);
		int avgX = minX + (maxX - minX) / 2;
		int avgZ = minZ + (maxZ - minZ) / 2;

		NBTTagCompound data = new NBTTagCompound();
		data.setString("type", "rbmkmush");
		data.setFloat("scale", smallDim);
		PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, avgX + 0.5, this.pos.getY() + 1, avgZ + 0.5), new TargetPoint(this.world.provider.getDimension(),avgX + 0.5, this.pos.getY() + 1, avgZ + 0.5, 250));
		MainRegistry.proxy.effectNT(data);

		this.world.playSoundEffect(avgX + 0.5, this.pos.getY() + 1, avgZ + 0.5, "hbm:block.rbmk_explosion", 50.0F, 1.0F);

		List<EntityPlayer> players = this.world.getEntitiesWithinAABB(EntityPlayer.class,
				AxisAlignedBB.getBoundingBox(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5, this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5).expand(50, 50, 50));

		for(EntityPlayer player : players) {
			com.hbm.advancement.NtmAdvancements.award(player, MainRegistry.achRBMKBoom);
		}

		if(RBMKBase.digamma) {
			EntitySpear spear = new EntitySpear(this.world);
			spear.posX = avgX + 0.5;
			spear.posZ = avgZ + 0.5;
			spear.posY = this.pos.getY() + 100;
			this.world.spawnEntityInWorld(spear);
		}

		RBMKBase.dropLids = true;
		RBMKBase.digamma = false;

		columns.clear();
		pipes.clear();
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.consumption = 0;
			this.output = 0;
			if(this.ventDelay > 0) this.ventDelay--;

			double heatCap = this.getHeatFromSteam(steam.getTankType());
			double heatProvided = this.heat - heatCap;

			if(heatProvided > 0) {
				double HEAT_PER_MB_WATER = RBMKDials.getBoilerHeatConsumption(this.world);
				double steamFactor = getFactorFromSteam(steam.getTankType());
				int waterUsed;
				int steamProduced;

				if(steam.getTankType() == Fluids.ULTRAHOTSTEAM) {
					steamProduced = (int)Math.floor((heatProvided / HEAT_PER_MB_WATER) * 100D / steamFactor);
					waterUsed = (int)Math.floor(steamProduced / 100D * steamFactor);

					if(feed.getFill() < waterUsed) {
						steamProduced = (int)Math.floor(feed.getFill() * 100D / steamFactor);
						waterUsed = (int)Math.floor(steamProduced / 100D * steamFactor);
					}
				} else {
					waterUsed = (int)Math.floor(heatProvided / HEAT_PER_MB_WATER);
					waterUsed = Math.min(waterUsed, feed.getFill());
					steamProduced = (int)Math.floor((waterUsed * 100D) / steamFactor);
				}

				this.consumption = waterUsed;
				this.output = steamProduced;

				feed.setFill(feed.getFill() - waterUsed);
				steam.setFill(steam.getFill() + steamProduced);

				if(steam.getFill() > steam.getMaxFill()) {
					steam.setFill(steam.getMaxFill());

					if(ventDelay <= 0) {
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "rbmksteam");
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, this.pos.getX() + 0.25 + this.world.rand.nextInt(2) * 0.5, this.pos.getY() + RBMKDials.getColumnHeight(this.world), this.pos.getZ() + 0.25 + this.world.rand.nextInt(2) * 0.5), new TargetPoint(this.world.provider.getDimension(), this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5, 100));
						MainRegistry.proxy.effectNT(data);
						this.ventDelay = 20 + this.world.rand.nextInt(10);
						this.world.playSoundEffect(this.pos.getX(), this.pos.getY() + RBMKDials.getColumnHeight(this.world), this.pos.getZ(), "hbm:block.steamEngineOperate", 2F, 1F + this.world.rand.nextFloat() * 0.25F);
					}
				}

				this.heat -= waterUsed * HEAT_PER_MB_WATER;
			}

			this.trySubscribe(feed.getTankType(), this.world, this.pos.getX(), this.pos.getY() - 1, this.pos.getZ(), Library.NEG_Y);
			for(DirPos pos : getOutputPos()) {
				if(this.steam.getFill() > 0) this.tryProvide(steam, this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}
		}

		super.update();
	}

@Override
	public void update() {
		prevHatchopen = hatchopen;
		prevHatchopen2 = hatchopen2;
		
		if (delay > 0) {
			delay--;
			return;
		}
		if(delay == 0) {
			hatchopen += (90 - hatchopen) * 0.2;
			hatchopen2 += (-90 - hatchopen2) * 0.2;
		}
		
		if (entityType != null && amount > 0 && !this.world.isRemote) {
			
			for (int i = 0; i < amount; i++) {

				Entity entity = EntityList.createEntityFromNBT(entityType, this.world);

				if (entity != null) {
					entity.setPosition(this.pos.getX() + 0.5, this.pos.getY() + 1, this.pos.getZ() + 0.5);

					this.world.spawnEntityInWorld(entity);
				}
			}

			amount = 0;	           
			this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.hatchOpen", 10.0F, 0.9F);
			return;

		}
		
		if(SpaceConfig.combatPodDespawn == true) {
			if(this.world.getTotalWorldTime() % 1000 == 0) {
				com.hbm.world.WorldAirRemoval.remove(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ());
			}
		}
	}

private void setState(int state) {
		this.world.setBlockMetadataWithNotify(this.pos.getX(), this.pos.getY(), this.pos.getZ(), state, 2);
		this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:block.reactorStart", 1.0F, 1.0F);
		updateState();
	}

