@Override
	public void updateFiringTick() {

		timer++;

		int delay = 40;

		if(timer % delay == 0) {

			if(this.hasAmmo() && this.tPos != null) {
				this.spawnShell(this.typeLoaded);
				this.ammo--;
				this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:weapon.rocketFlame", 25.0F, 1.0F);
			}

			if(this.mode == this.MODE_MANUAL && !this.targetQueue.isEmpty()) {
				this.targetQueue.remove(0);
				this.tPos = null;
			}
		}
	}

@Override
	public void update() {

		if(this.world.isRemote) {

			this.lastSpin = this.spin;

			if(this.tPos != null) {
				this.spin += 45;
			}

			if(this.spin >= 360F) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}
		} else {

			if(loaded <= 0) {
				BulletConfig conf = this.getFirstConfigLoaded();

				if(conf != null) {
					this.conusmeAmmo(conf.ammo);
					this.world.playSoundEffect(this.pos.getX(), this.pos.getY(), this.pos.getZ(), "hbm:turret.howard_reload", 4.0F, 1F);
					loaded = 200;
				}
			}
		}

		super.update();
	}

